import json, math
from pathlib import Path
from pyscipopt import Model, quicksum

START, END = 'depot_start', 'depot_end'
data=json.loads(Path('/root/data.json').read_text())
stations=data['stations']; n=len(stations); K=range(data['vehicle_count']); N=range(n); C=data['vehicle_capacity']
def dist(a,b):
 d=math.pi/180
 p1=(90-a['latitude'])*d; p2=(90-b['latitude'])*d; t1=a['longitude']*d; t2=b['longitude']*d
 co=math.sin(p1)*math.sin(p2)*math.cos(t1-t2)+math.cos(p1)*math.cos(p2)
 return math.acos(max(-1,min(1,co)))*3960.0
locations={START:data['depot'],END:data['depot']}|{i:s for i,s in enumerate(stations)}
arcs=[(i,j) for i in [START,*N] for j in [*N,END] if i!=j]
distance={(i,j):dist(locations[i],locations[j]) for i,j in arcs}
m=Model('bike');m.hideOutput()
x={(k,i,j):m.addVar(vtype='B') for k in K for i,j in arcs}
v={(k,i):m.addVar(vtype='B') for k in K for i in N}
o={(k,i):m.addVar(lb=0,ub=n) for k in K for i in N}
p={(k,i):m.addVar(vtype='I',lb=0,ub=C) for k in K for i in N}
d={(k,i):m.addVar(vtype='I',lb=0,ub=C) for k in K for i in N}
pmode={(k,i):m.addVar(vtype='B') for k in K for i in N}; dmode={(k,i):m.addVar(vtype='B') for k in K for i in N}
sload={k:m.addVar(vtype='I',lb=0,ub=C) for k in K}; load={(k,i):m.addVar(vtype='I',lb=0,ub=C) for k in K for i in N}; eload={k:m.addVar(vtype='I',lb=0,ub=C) for k in K}
u={i:m.addVar(vtype='I',lb=0) for i in N}
for k in K:
 m.addCons(quicksum(x[k,START,i] for i in N)==1);m.addCons(quicksum(x[k,i,END] for i in N)==1)
 for i in N:
  inc=quicksum(x[k,j,i] for j in [START,*N] if j!=i); out=quicksum(x[k,i,j] for j in [*N,END] if j!=i)
  m.addCons(inc==v[k,i]);m.addCons(out==v[k,i]);m.addCons(o[k,i]>=v[k,i]);m.addCons(o[k,i]<=n*v[k,i])
  m.addCons(p[k,i]<=C*pmode[k,i]);m.addCons(d[k,i]<=C*dmode[k,i]);m.addCons(pmode[k,i]+dmode[k,i]<=v[k,i])
  z=sload[k]+p[k,i]-d[k,i]
  m.addCons(load[k,i]-z<=2*C*(1-x[k,START,i]));m.addCons(z-load[k,i]<=2*C*(1-x[k,START,i]))
  m.addCons(eload[k]-load[k,i]<=C*(1-x[k,i,END]));m.addCons(load[k,i]-eload[k]<=C*(1-x[k,i,END]))
 for i in N:
  for j in N:
   if i==j: continue
   m.addCons(o[k,i]-o[k,j]+n*x[k,i,j]<=n-1)
   z=load[k,i]+p[k,j]-d[k,j]
   m.addCons(load[k,j]-z<=2*C*(1-x[k,i,j]));m.addCons(z-load[k,j]<=2*C*(1-x[k,i,j]))
for i in N:
 tp=quicksum(p[k,i] for k in K); td=quicksum(d[k,i] for k in K); target=stations[i]['net_rebalancing_target']
 m.addCons(stations[i]['initial_bikes']-tp+td>=0);m.addCons(stations[i]['initial_bikes']-tp+td<=stations[i]['station_capacity'])
 m.addCons(tp-td-target<=u[i]);m.addCons(target-tp+td<=u[i])
travel=quicksum(distance[i,j]*x[k,i,j] for k in K for i,j in arcs)
m.setObjective(travel+data['penalty_weight']*quicksum(u.values()),'minimize');m.setParam('limits/time',300.0);m.setParam('limits/gap',0.0);m.optimize()
print('status',m.getStatus(),'sols',m.getNSols(),'obj',m.getObjVal())
if not m.getNSols(): raise RuntimeError('no solution')
def val(z): return int(round(m.getVal(z)))
vr=[]
for k in K:
 nxt={i:j for i,j in arcs if m.getVal(x[k,i,j])>.5}; route=[START]
 while route[-1]!=END:route.append(nxt[route[-1]])
 stops=[{'station_id':stations[i]['id'],'bikes_picked_up':float(val(p[k,i])),'bikes_dropped_off':float(val(d[k,i])),'load_after_stop':float(val(load[k,i]))} for i in route[1:-1]]
 vr.append({'vehicle_id':k+1,'start_load':float(val(sload[k])),'route':[z if isinstance(z,str) else stations[z]['id'] for z in route],'stops':stops,'end_load':float(val(eload[k])})
sr=[]
for i in N:
 tp=sum(val(p[k,i]) for k in K);td=sum(val(d[k,i]) for k in K);t=stations[i]['net_rebalancing_target']
 sr.append({'station_id':stations[i]['id'],'net_rebalancing_target':float(t),'total_bikes_picked_up':float(tp),'total_bikes_dropped_off':float(td),'net_bike_change':float(tp-td),'unmet_rebalancing_amount':float(abs(t-tp+td))})
tv=sum(distance[i,j]*m.getVal(x[k,i,j]) for k in K for i,j in arcs); uv=sum(s['unmet_rebalancing_amount'] for s in sr)
report={'summary':{'objective':tv+data['penalty_weight']*uv,'travel_distance_miles':tv,'unmet_rebalancing_penalty':data['penalty_weight']*uv,'total_unmet_rebalancing_amount':uv},'vehicles':vr,'stations':sr}
Path('/root/report.json').write_text(json.dumps(report,indent=2)+'\n')
